const char* AP_PASSWORD = "Music1234";
const char* SETTINGS_PIN = "1234";

static const int LDR_PIN = 34;
static const int DF_RX_ESP = 16; // ESP32 receives from DFPlayer TX
static const int DF_TX_ESP = 17; // ESP32 transmits to DFPlayer RX via 1k resistor
static const int LIGHT_THRESHOLD_DEFAULT = 3000;
