  {"Christmas song 001",3,1},{"Christmas song 002",3,2}
};
const size_t SONG_COUNT = sizeof(SONGS)/sizeof(SONGS[0]);

HardwareSerial dfSerial(2);
DFRobotDFPlayerMini player;
WebServer server(80);
bool playerReady=false, lightIsOn=false, isPlaying=false, settingsUnlocked=false;
int lightThreshold=LIGHT_THRESHOLD_DEFAULT, hysteresis=HYSTERESIS_DEFAULT, volumeLevel=VOLUME_DEFAULT;
int lastAdc=0; unsigned long lastSensorRead=0, unlockUntil=0;
int queuedSong=-1; int currentSong=-1; String currentTitle="Nothing playing";

String jsonEscape(const char* s){ String o; while(*s){char c=*s++; if(c=='"'||c=='\\')o+='\\'; if(c=='\n')o+="\\n"; else o+=c;} return o; }
void playSong(int index){ if(!playerReady || index<0 || index>=(int)SONG_COUNT)return; const Song &s=SONGS[index]; player.playFolder(s.folder,s.track); currentSong=index; currentTitle=s.title; isPlaying=true; }
int randomDefault(){ return random(0,DEFAULT_TRACKS); }
bool christmasSeason(){ struct tm t; if(!getLocalTime(&t,20))return false; int m=t.tm_mon+1,d=t.tm_mday; return (m==11)||(m==12)||(m==1 && d<=1); }
void onLightOn(){
  if(queuedSong>=0){int q=queuedSong; queuedSong=-1; playSong(q); return;}
  if(christmasSeason() && random(100)<CHRISTMAS_CHANCE_PERCENT){ int picks[32],n=0; for(size_t i=0;i<SONG_COUNT;i++)if(SONGS[i].folder==3 && n<32)picks[n++]=i; if(n){playSong(picks[random(n)]);return;} }
  // Folder 1 is reserved for the automatic playlist; tracks 1..70.
  player.playFolder(1, random(1,DEFAULT_TRACKS+1)); currentSong=-1; currentTitle="Random default song"; isPlaying=true;
}
void sensorTick(){ if(millis()-lastSensorRead<100)return; lastSensorRead=millis(); lastAdc=analogRead(LDR_PIN);
  // Existing tested setup: illuminated sensor reads lower than covered/dark sensor.
  bool next=lightIsOn; if(!lightIsOn && lastAdc<(lightThreshold-hysteresis/2))next=true; else if(lightIsOn && lastAdc>(lightThreshold+hysteresis/2))next=false;
  if(next!=lightIsOn){lightIsOn=next; if(lightIsOn)onLightOn(); else { if(playerReady)player.pause(); isPlaying=false; }}
}
String page(){ return R"HTML(<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f4f0e8"><title>Bathroom Music</title><style>
:root{color-scheme:light}*{box-sizing:border-box}body{margin:0;background:#f4f0e8;color:#242424;font:16px system-ui;max-width:650px;padding:22px;margin:auto}h1{font-size:27px;margin:8px 0}p{color:#666}.card{background:white;border-radius:18px;padding:17px;margin:14px 0;box-shadow:0 2px 12px #0000000a}input,button{font:inherit;border-radius:12px;padding:12px;border:1px solid #ddd}input{width:100%;margin:7px 0}button{background:#242424;color:white;border:0;margin:4px;cursor:pointer}.secondary{background:#eee;color:#222}.row{display:flex;gap:6px;flex-wrap:wrap}.row button{flex:1}.small{font-size:13px;color:#777}#results button{display:block;width:100%;text-align:left;background:#eee;color:#222;margin:5px 0}details{margin-top:24px}#settings{display:none}</style></head><body>
<div class="small">BATHROOM AUDIO</div><h1>Bathroom Music 🎵</h1><div class="card"><div id="status">Connecting…</div><p id="track">Nothing playing</p><div class="row"><button onclick="cmd('/play')">▶ Play</button><button onclick="cmd('/pause')" class="secondary">Ⅱ Pause</button></div><label>Volume <span id="voltxt">20</span></label><input type="range" min="0" max="30" value="20" oninput="voltxt.textContent=this.value" onchange="cmd('/volume?v='+this.value)"></div>
<div class="card"><h3>Find a song</h3><input id="q" placeholder="Search songs…" oninput="searchSongs()"><div id="results"></div></div>
<div class="card"><h3>Queue a prank song 😈</h3><p class="small">Choose a song to play the next time the light turns on. It overrides the random selection once.</p><input id="prank" placeholder="Search for a song to queue"><div id="prankresults"></div></div>
<details><summary>⚙ Settings & diagnostics</summary><div id="settings"><div class="card"><label>Light threshold</label><input id="threshold" type="number" min="0" max="4095"><label>Hysteresis</label><input id="hyst" type="number" min="0" max="1000"><input id="pin" type="password" placeholder="Settings PIN"><button onclick="saveSettings()">Save settings</button><p id="diag"></p></div></div><div class="card"><input id="unlockpin" type="password" placeholder="PIN"><button onclick="unlock()">Unlock settings</button></div></details>
<script>
async function cmd(p){let r=await fetch(p);let t=await r.text();if(t.startsWith('Queued'))alert(t);refresh()} async function refresh(){try{let s=await(await fetch('/status')).json();status.textContent=(s.light?'💡 Light detected':'🌑 Light off')+' · '+(s.playing?'Playing':'Paused')+' · Wi-Fi '+s.wifi;track.textContent=s.title;voltxt.textContent=s.volume;document.querySelector('input[type=range]').value=s.volume;if(s.unlocked){settings.style.display='block';threshold.value=s.threshold;hyst.value=s.hysteresis;diag.textContent='Sensor ADC: '+s.adc+' / 4095';}}catch(e){status.textContent='Connection lost';}}
async function find(q,target){let a=await(await fetch('/search?q='+encodeURIComponent(q))).json();target.innerHTML='';a.forEach(s=>{let b=document.createElement('button');b.textContent=s.title+' · folder '+s.folder;b.onclick=()=>cmd((target.id==='prankresults'?'/queue?id=':'/select?id=')+s.id);target.appendChild(b);});}
function searchSongs(){find(q.value,results)} prank.addEventListener('input',()=>find(prank.value,prankresults));async function unlock(){let r=await fetch('/unlock?pin='+encodeURIComponent(unlockpin.value));if(r.ok)refresh();else alert('Incorrect PIN');}async function saveSettings(){let r=await fetch('/settings?pin='+encodeURIComponent(pin.value)+'&threshold='+threshold.value+'&hysteresis='+hyst.value);alert(r.ok?'Settings saved':'Unlock again first');refresh();}setInterval(refresh,2000);refresh();
</script></body></html>)HTML"; }
void sendStatus(){String j="{"; j+="\"light\":"+String(lightIsOn?"true":"false")+",\"playing\":"+String(isPlaying?"true":"false")+",\"wifi\":\""+String(WiFi.status()==WL_CONNECTED?"home":"hotspot")+"\",\"title\":\""+jsonEscape(currentTitle.c_str())+"\",\"volume\":"+String(volumeLevel)+",\"adc\":"+String(lastAdc)+",\"threshold\":"+String(lightThreshold)+",\"hysteresis\":"+String(hysteresis)+",\"unlocked\":"+String(settingsUnlocked && millis()<unlockUntil?"true":"false")+"}"; server.send(200,"application/json",j);}
void setupWeb(){
 server.on("/",HTTP_GET,[]{server.send(200,"text/html",page());});
 server.on("/status",HTTP_GET,sendStatus);
 server.on("/play",HTTP_GET,[]{if(playerReady){if(currentSong>=0)player.start();else onLightOn();isPlaying=true;}server.send(200,"text/plain","OK");});
 server.on("/pause",HTTP_GET,[]{if(playerReady)player.pause();isPlaying=false;server.send(200,"text/plain","OK");});
 server.on("/volume",HTTP_GET,[]{if(server.hasArg("v")){volumeLevel=constrain(server.arg("v").toInt(),0,30);if(playerReady)player.volume(volumeLevel);}server.send(200,"text/plain","OK");});
 server.on("/search",HTTP_GET,[]{String q=server.arg("q");q.toLowerCase();String j="[";bool first=true;for(size_t i=0;i<SONG_COUNT;i++){String t=SONGS[i].title;t.toLowerCase();if(q.length()==0||t.indexOf(q)>=0){if(!first)j+=",";first=false;j+="{\"id\":"+String(i)+",\"folder\":"+String(SONGS[i].folder)+",\"title\":\""+jsonEscape(SONGS[i].title)+"\"}";}}j+="]";server.send(200,"application/json",j);});
 server.on("/select",HTTP_GET,[]{int id=server.arg("id").toInt();if(id>=0&&id<(int)SONG_COUNT){playSong(id);server.send(200,"text/plain","OK");}else server.send(400,"text/plain","Bad song id");});
 server.on("/queue",HTTP_GET,[]{int id=server.arg("id").toInt();if(id>=0&&id<(int)SONG_COUNT){queuedSong=id;server.send(200,"text/plain","Queued for next light-on");}else server.send(400,"text/plain","Bad song id");});
 server.on("/unlock",HTTP_GET,[]{if(server.arg("pin")==SETTINGS_PIN){settingsUnlocked=true;unlockUntil=millis()+300000;server.send(200,"text/plain","OK");}else server.send(403,"text/plain","Wrong PIN");});
 server.on("/settings",HTTP_GET,[]{if(!(settingsUnlocked&&millis()<unlockUntil)&&server.arg("pin")!=SETTINGS_PIN){server.send(403,"text/plain","Locked");return;}lightThreshold=constrain(server.arg("threshold").toInt(),0,4095);hysteresis=constrain(server.arg("hysteresis").toInt(),0,1000);settingsUnlocked=true;unlockUntil=millis()+300000;server.send(200,"text/plain","OK");});
 server.begin();
}
void setup(){Serial.begin(115200);analogReadResolution(12);pinMode(LDR_PIN,INPUT);randomSeed(analogRead(35));
 dfSerial.begin(9600,SERIAL_8N1,DF_RX_ESP,DF_TX_ESP);delay(500);playerReady=player.begin(dfSerial,false,true);if(playerReady){player.volume(volumeLevel);player.EQ(DFPLAYER_EQ_NORMAL);}
 WiFi.mode(WIFI_AP_STA);WiFi.softAP(AP_SSID,AP_PASSWORD);
 if(String(WIFI_SSID)!="YOUR_WIFI_NAME" && strlen(WIFI_SSID)>0){WiFi.begin(WIFI_SSID,WIFI_PASSWORD);unsigned long start=millis();while(WiFi.status()!=WL_CONNECTED&&millis()-start<12000)delay(250);if(WiFi.status()==WL_CONNECTED){configTime(0,0,"pool.ntp.org","time.google.com");if(MDNS.begin("bathroommusic"))MDNS.addService("http","tcp",80);}}
 setupWeb();lastAdc=analogRead(LDR_PIN);lightIsOn=(lastAdc<lightThreshold);if(lightIsOn)onLightOn();
 Serial.println("Bathroom Music Controller ready");Serial.print("AP address: ");Serial.println(WiFi.softAPIP());if(WiFi.status()==WL_CONNECTED){Serial.print("Home Wi-Fi address: ");Serial.println(WiFi.localIP());}
}
void loop(){server.handleClient();sensorTick();if(settingsUnlocked&&millis()>unlockUntil)settingsUnlocked=false;delay(2);}
